import fs from "node:fs";
import path from "node:path";
import {createHash,timingSafeEqual} from "node:crypto";
import {execFileSync} from "node:child_process";

const root=path.resolve(process.argv[2]??"."),expected=process.argv[3],manifestOut=process.argv[4];
const frame=value=>{const bytes=Buffer.isBuffer(value)?value:Buffer.from(String(value),"utf8");return Buffer.concat([Buffer.from(`${bytes.length}:`,"ascii"),bytes])};
const top=fs.realpathSync(execFileSync("git",["-C",root,"rev-parse","--show-toplevel"],{encoding:"utf8"}).trim());if(top!==fs.realpathSync(root))throw new Error("authority root must equal repository root");
let writeTree,headTree,status;try{writeTree=execFileSync("git",["-C",root,"write-tree"],{encoding:"utf8"}).trim();headTree=execFileSync("git",["-C",root,"rev-parse","HEAD^{tree}"],{encoding:"utf8"}).trim();execFileSync("git",["-C",root,"diff-files","--quiet","--"],{stdio:"ignore"});status=execFileSync("git",["-C",root,"status","--porcelain=v2","-z","--untracked-files=all","--ignored=matching"],{maxBuffer:64*1024*1024})}catch{throw new Error("clean HEAD required for production policy bundle")};if(writeTree!==headTree||status.length!==0)throw new Error("clean HEAD required for production policy bundle");
const index=execFileSync("git",["-C",root,"ls-files","--stage","-z"],{maxBuffer:64*1024*1024}),entries=[];for(const raw of index.toString("utf8").split("\0").filter(Boolean)){const match=raw.match(/^(100644|100755|120000) ([a-f0-9]{40,64}) 0\t(.+)$/s);if(!match)throw new Error("authority git index entry rejected");if(match[1]==="120000")throw new Error(`authority closure rejects symlink: ${match[3]}`);entries.push({path:match[3],oid:match[2],mode:match[1]==="100755"?0o755:0o644})}entries.sort((a,b)=>Buffer.from(a.path).compare(Buffer.from(b.path)));if(new Set(entries.map(x=>x.path)).size!==entries.length)throw new Error("duplicate authority path");
const tracked=new Set(entries.map(entry=>entry.path)),trackedDirectories=new Set(entries.flatMap(entry=>{const parts=entry.path.split("/");return parts.slice(0,-1).map((_,index)=>parts.slice(0,index+1).join("/"))})),walk=(directory,relative="")=>{for(const item of fs.readdirSync(directory,{withFileTypes:true})){if(!relative&&item.name===".git")continue;const child=relative?`${relative}/${item.name}`:item.name;if(item.isDirectory()){if(!trackedDirectories.has(child))throw new Error(`clean HEAD required for production policy bundle: untracked directory ${child}`);walk(path.join(directory,item.name),child)}else if(!tracked.has(child))throw new Error(`clean HEAD required for production policy bundle: untracked path ${child}`)}};walk(root);
const hash=createHash("sha256"),manifest=[];for(const entry of entries){const bytes=execFileSync("git",["-C",root,"cat-file","blob",entry.oid],{maxBuffer:256*1024*1024}),declared=Number(execFileSync("git",["-C",root,"cat-file","-s",entry.oid],{encoding:"utf8"}).trim());if(!Number.isSafeInteger(declared)||declared!==bytes.length)throw new Error(`authority blob size mismatch: ${entry.path}`);const contentSha256=createHash("sha256").update(bytes).digest("hex"),mode=entry.mode.toString(8);manifest.push({path:entry.path,type:"regular",mode,size:bytes.length,sha256:contentSha256});for(const field of ["regular",entry.path,mode,String(bytes.length),bytes])hash.update(frame(field))}const digest=hash.digest("hex");
if(expected!==undefined){if(!/^[a-f0-9]{64}$/.test(expected)||!timingSafeEqual(Buffer.from(digest,"hex"),Buffer.from(expected,"hex")))throw new Error("protected production policy bundle digest mismatch")}
if(manifestOut)fs.writeFileSync(manifestOut,JSON.stringify({schemaVersion:1,purpose:"production-authority-closure",digest,entries:manifest})+"\n",{flag:"wx",mode:0o600});
process.stdout.write(`${digest}\n`);
